mcdnnHandle_t GetMcdnnHandle(int device) {
  static thread_local std::unordered_map<int, mcdnnHandle_t> handles;
  auto& handle = handles[device];
  if (!handle) {
    const auto status = mcdnnCreate(&handle);
    TORCH_CHECK(status == MCDNN_STATUS_SUCCESS,
        "MACA softmax handle: ", mcdnnGetErrorString(status));
  }
  const auto stream = reinterpret_cast<mcStream_t>(GetCurrentStreamForDevice(device));
  const auto status = mcdnnSetStream(handle, stream);
  TORCH_CHECK(status == MCDNN_STATUS_SUCCESS,
      "MACA softmax stream: ", mcdnnGetErrorString(status));
  return handle;
}

